sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* ════════════════════════════════════════
   SIDEBAR — FIXED & REFINED
════════════════════════════════════════ */
.dm-sidebar {
  width: 100%;
  height: 100vh;
  background: linear-gradient(160deg, #2d2669 0%, #4a3fa0 50%, #6b5fd4 100%);
  border-right: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  position: sticky;
  top: 0;
  box-sizing: border-box;
  overflow: hidden;
  /* ✅ removed margin-top: 13% — was the main spacing bug */
}

/* subtle inner shadow on right edge */
.dm-sidebar::after {
  content: '';
  position: absolute; top: 0; right: 0;
  width: 1px; height: 100%;
  background: rgba(255,255,255,0.08);
  pointer-events: none;
}

/* ════════════════════════════════════════
   LOGO / BRAND SECTION
════════════════════════════════════════ */
.dm-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 22px 20px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  cursor: pointer;
  text-decoration: none;
  flex-shrink: 0;
}

.dm-logo-icon {
  width: 36px; height: 36px;
  background: rgba(255,255,255,0.18);
  border: 1px solid rgba(255,255,255,0.2);
  color: #fff;
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px;
  flex-shrink: 0;
}

.dm-logo-text { min-width: 0; }

.dm-title {
  display: block;
  font-weight: 700;
  font-size: 13px;
  color: #ffffff;
  letter-spacing: -.1px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dm-sub {
  display: block;
  font-size: 10px;
  color: rgba(255,255,255,0.55);
  margin-top: 1px;
  letter-spacing: .2px;
}

/* ════════════════════════════════════════
   NAV SECTION LABEL
════════════════════════════════════════ */
.dm-nav-label {
  font-size: 9px;
  font-weight: 700;
  color: rgba(255,255,255,0.4);
  text-transform: uppercase;
  letter-spacing: .8px;
  padding: 18px 20px 8px;
}

/* ════════════════════════════════════════
   MENU LIST
════════════════════════════════════════ */
.dm-menu {
  list-style: none;
  padding: 8px 12px;
  margin: 0;
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
}

/* hide scrollbar but keep scroll */
.dm-menu::-webkit-scrollbar { width: 0; }

.dm-menu li {
  margin-bottom: 2px;
}

/* ── Base link ── */
.dm-menu a {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  border-radius: 10px;
  text-decoration: none;
  font-size: 13px;
  font-weight: 500;
  color: rgba(255,255,255,0.75);
  position: relative;
  transition:
    background .18s ease,
    color .18s ease,
    padding-left .18s ease;
}

/* ── Icon ── */
.dm-menu a i {
  width: 20px;
  text-align: center;
  font-size: 14px;
  color: rgba(255,255,255,0.6);
  flex-shrink: 0;
  transition: color .18s ease, transform .18s ease;
}

/* ── Hover ── */
.dm-menu li:not(.active) a:hover {
  background: rgba(255,255,255,0.1);
  color: #ffffff;
  padding-left: 15px;
}
.dm-menu li:not(.active) a:hover i {
  color: #ffffff;
  transform: scale(1.1);
}

/* ── Active state — white pill + left accent bar ── */
.dm-menu li.active a {
  background: rgba(255,255,255,0.18);
  color: #ffffff;
  font-weight: 700;
  padding-left: 15px;
  box-shadow: inset 3px 0 0 #ffffff;  /* ← left accent bar */
}
.dm-menu li.active a i {
  color: #ffffff;
}

/* ════════════════════════════════════════
   FOOTER
════════════════════════════════════════ */
.dm-footer {
  flex-shrink: 0;
  padding: 14px 20px 18px;
  border-top: 1px solid rgba(255,255,255,0.1);
  font-size: 10px;
  color: rgba(255,255,255,0.4);
  letter-spacing: .1px;
}
.dm-version {
  margin-top: 2px;
  font-size: 9px;
  color: rgba(255,255,255,0.3);
}
